CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_mantenimientos_alerta` AS select `ds`.`id_detalle_servicio` AS `id_detalle_servicio`,`v`.`id_vehiculo` AS `id_vehiculo`,`v`.`placa` AS `placa`,`v`.`propietario` AS `propietario`,`s`.`nombre` AS `servicio`,`ds`.`fecha_proximo_servicio` AS `fecha_proximo_servicio`,(case when (`ds`.`fecha_proximo_servicio` < curdate()) then 'Vencido' when (`ds`.`fecha_proximo_servicio` <= (curdate() + interval 7 day)) then 'Proximo' else 'Programado' end) AS `estado_alerta` from (((`detalle_servicio` `ds` join `ordenes_trabajo` `o` on((`o`.`id_orden` = `ds`.`id_orden`))) join `vehiculos` `v` on((`v`.`placa` = `o`.`placa`))) join `servicios` `s` on((`s`.`id_servicio` = `ds`.`id_servicio`))) where ((`ds`.`estado_mantenimiento` = 'Realizado') and (`ds`.`fecha_proximo_servicio` is not null));
